import{z as s,x as i,o as l,c as D,q as A,j as e,D as t,d as B,s as n,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"调度收束","description":"","frontmatter":{"title":"调度收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-map.md","filePath":"llm/sch-map.md","lastUpdated":1791413859000}'),d={name:"llm/sch-map.md"};function C(p,E,g,m,h,T){const o=i("Mermaid");return l(),D("div",null,[E[2]||(E[2]=A('<h1 id="调度收束" tabindex="-1">调度收束 <a class="header-anchor" href="#调度收束" aria-label="Permalink to &quot;调度收束&quot;">​</a></h1><div class="epigraph"><p>收束不是把十二课再讲一遍，是把它们压成一张先后表：先立账本，再组批，再定策略，再谈资源从哪来、不够怎么办。</p><footer>—— 据 Kwon et al., SOSP 2023 与 Zhong et al., OSDI 2024 的系统口径，按本课程整理</footer></div><p><a href="/llm/sch-multitenant-isolation">上一课</a>把租户维收进三道配额。至此本课程的零件齐了：指标、批、优先级、合同、抢占、分离、适配器、路由、过载、伸缩、隔离。上游是 <a href="/llm/kv-map">KV 管理收束</a> 回答的「池子怎么管」，本课程回答「池子怎么用」。本课收束：把十二课装配成一张依赖图与一张决策单。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>十二个机制分属三层：<strong>机制</strong>（批与预算、抢占）、<strong>策略</strong>（优先级、公平、分层）、<strong>资源</strong>（PD 池、适配器、路由、伸缩、隔离）。各自局部最优会互相拆台：路由为命中率把负载集中，伸缩为均衡把前缀打散；降级截断上下文，前缀命中率跟着掉；抢占保住新请求的 TTFT，打穿老请求的 TPOT 合同；适配器驻留吃掉的显存正是 KV 池的地皮。没有全局顺序，团队会在错误的位置先动刀——最常见的两条弯路：没有指标合同就调参（改完不知道好坏），跳过步内预算直接上 PD 分离（用大手术治预算能治的病）。<span class="marginnote">常见误区：初学者容易一上来就调批大小，或者直接上 PD 分离这种「大手术」。但账本没立，改完说不清是变好还是变坏；步内预算没常数化，排序排得再巧，一条 8k 长前填插进来照样全线打穿。顺序错了，力气花在错的位置。</span>收束要给的就是这张先后表。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>决策单</strong>，按依赖排序：</p><ol><li><strong>指标合同</strong>：双分位数（TTFT、TPOT）加 goodput，分租户分类别记账。一切评审的账本；没有它，后面每一步都无法验收。</li><li><strong>批与预算</strong>：token 预算、decode 先装、prefill 切块，把最坏步时延变成常数。这是策略的落点：没有常数上界，任何排序都会被一条长前填打穿。</li><li><strong>策略层</strong>：优先级定序、公平份额保底、SLO 分层定合同、三道配额防占坑。</li><li><strong>执行层</strong>：抢占按三本账选路（重算、换出、迁移），让优先级在迭代边界有牙齿。</li><li><strong>放置层</strong>：PD 配比、适配器驻留、缓存感知路由——三个同构的放置问题，命中与均衡联评。</li><li><strong>运维层</strong>：过载三道闸、弹性伸缩的暖池与排干、隔离的对抗验收。</li></ol><p>每层拿上一层吐不出的余量：合同没立，机制无从评审；预算没有，策略没有落点；放置没做对，运维在错的位置扩容。</p>',9)),(l(),e(r,null,{default:t(()=>[n(o,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20CONTRACT%5B%22%E6%8C%87%E6%A0%87%E5%90%88%E5%90%8C%EF%BC%9A%E5%8F%8C%E5%88%86%E4%BD%8D%E4%B8%8E%20goodput%22%5D%20--%3E%20BATCH%5B%22%E6%89%B9%E4%B8%8E%20token%20%E9%A2%84%E7%AE%97%22%5D%0A%20%20BATCH%20--%3E%20POL%5B%22%E7%AD%96%E7%95%A5%EF%BC%9A%E4%BC%98%E5%85%88%E7%BA%A7%20%2F%20%E5%85%AC%E5%B9%B3%20%2F%20%E5%88%86%E5%B1%82%20%2F%20%E9%85%8D%E9%A2%9D%22%5D%0A%20%20POL%20--%3E%20EXEC%5B%22%E6%89%A7%E8%A1%8C%EF%BC%9A%E6%8A%A2%E5%8D%A0%E4%B8%89%E6%9C%AC%E8%B4%A6%22%5D%0A%20%20BATCH%20--%3E%20PLACE%5B%22%E6%94%BE%E7%BD%AE%EF%BC%9APD%20%E9%85%8D%E6%AF%94%20%2F%20LoRA%20%E9%A9%BB%E7%95%99%20%2F%20%E7%BC%93%E5%AD%98%E8%B7%AF%E7%94%B1%22%5D%0A%20%20POL%20--%3E%20PLACE%0A%20%20EXEC%20--%3E%20OPS%5B%22%E8%BF%90%E7%BB%B4%EF%BC%9A%E8%BF%87%E8%BD%BD%E9%98%B6%E6%A2%AF%E5%88%B0%E4%BC%B8%E7%BC%A9%E5%88%B0%E9%9A%94%E7%A6%BB%E9%AA%8C%E6%94%B6%22%5D%0A%20%20PLACE%20--%3E%20OPS%0A%20%20OPS%20--%3E%20LED%5B%22goodput%20%E8%B4%A6%E6%9C%AC%E5%9B%9E%E8%AF%84%22%5D%0A%20%20LED%20--%3E%20CONTRACT%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("贯穿十二课的地形是三对张力："),a("strong",null,"吞吐与尾延迟"),B("——帕累托前沿不可同时最优，预算与分层是把前沿显式化的工具；"),a("span",{class:"marginnote"},"术语翻译：帕累托前沿就是「鱼与熊掌的边界线」——把所有「不可能两全」的组合画成一条曲线，线上每一点都已是能拿到的最好交易；想多要一点尾延迟余量，就必须让出一点吞吐。说某个配置「在前沿上」，意思是没有免费的改进空间了，再动就有一头要付账。"),a("strong",null,"隔离与利用率"),B("——份额切多细，峰值共享丢多少，超卖比例是定价；"),a("span",{class:"marginnote"},"数字实例：10 个租户各买一卡的份额，但实测平均同时只用六成，按 1.5 倍超卖大约 4 张卡就能接住期望负载，省下 6 张卡的钱；代价是节日流量全体同时打满时，尾部延迟违约的风险由你承担——超卖比例不是技术参数，是风险定价。"),a("strong",null,"命中与均衡"),B("——亲和与水位在每个放置决策里对峙。调度器的工作不是消解张力，是把张力标价：每个机制注明它在三条轴上各花多少，按合同付账。另一个贯穿机制是「常数化」：token 预算把最坏步时延变成常数，水位加滞回把抢占变成有界事件，按层传输把迁移时间变成层数的函数——好的调度设计都在把「取决于邻居与运气」改成「取决于配置」。「常数化」前后，同一个系统面对同一条长前填的表现：")],-1)),(l(),e(r,null,{default:t(()=>[n(o,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20RAW%5B%22%E6%9C%AA%E5%B8%B8%E6%95%B0%E5%8C%96%EF%BC%9A%E7%9C%8B%E8%BF%90%E6%B0%94%E4%B8%8E%E9%82%BB%E5%B1%85%22%5D%0A%20%20%20%20L1%5B%22%E4%B8%80%E6%9D%A1%208k%20%E5%89%8D%E5%A1%AB%E6%95%B4%E6%AD%A5%E6%8F%92%E9%98%9F%22%5D%20--%3E%20X1%5B%22%E6%9C%80%E5%9D%8F%E6%AD%A5%E6%97%B6%E5%BB%B6%E6%97%A0%E4%B8%8A%E7%95%8C%22%5D%0A%20%20%20%20X1%20--%3E%20Y1%5B%22ITL%20%E5%90%88%E5%90%8C%E9%9A%8F%E6%9C%BA%E8%A2%AB%E6%89%93%E7%A9%BF%22%5D%0A%20%20%20%20E1%5B%22%E6%B0%B4%E4%BD%8D%E4%B8%80%E6%8A%96%E5%B0%B1%E8%A7%A6%E5%8F%91%E6%8A%A2%E5%8D%A0%22%5D%20--%3E%20Y1%0A%20%20end%0A%20%20subgraph%20CONST%5B%22%E5%B8%B8%E6%95%B0%E5%8C%96%EF%BC%9A%E7%9C%8B%E9%85%8D%E7%BD%AE%22%5D%0A%20%20%20%20C1%5B%22token%20%E9%A2%84%E7%AE%97%20%2B%20prefill%20%E5%88%87%E5%9D%97%22%5D%20--%3E%20Z1%5B%22%E6%9C%80%E5%9D%8F%E6%AD%A5%E6%97%B6%E5%BB%B6%20%3D%20%E5%B8%B8%E6%95%B0%22%5D%0A%20%20%20%20C2%5B%22%E6%B0%B4%E4%BD%8D%20%2B%20%E6%BB%9E%E5%9B%9E%22%5D%20--%3E%20Z2%5B%22%E6%8A%A2%E5%8D%A0%E6%88%90%E4%B8%BA%E6%9C%89%E7%95%8C%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20end%0A%20%20RAW%20--%3E%7C%22%E6%8A%8A%E4%B8%8A%E7%95%8C%E4%BB%8E%E8%BF%90%E6%B0%94%E6%90%AC%E8%BF%9B%E9%85%8D%E7%BD%AE%22%7C%20CONST%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">一张自检表：如果只能做三件事——先立双分位与 goodput 合同（分租户）；再配 token 预算与 chunked prefill（最坏步时延变常数）；然后上每租户三道配额。多数服务在这三步之前已拿到大半收益，后面的每一刀都要求先证明前面拿不出来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这张地图有时效。架构侧：GQA、MLA 把 KV 基数改小，池子变大，水位、配比、配额的每一个常数要重标；投机解码改变每步的工作量分布，预算与 ITL 地板要重算。负载侧：agent 化让输出更长、会话更黏，配比与亲和的权重漂移。地图之外：池子怎么管在 KV 管理课程，token 之下是内核与数值层——各自的地图由相邻课程交付。本课程交付的是中间这一层：<strong>池子怎么用</strong>的地图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策单按依赖排序：合同 → 批与预算 → 策略 → 执行 → 放置 → 运维。</li><li>三对张力贯穿：吞吐-尾延迟、隔离-利用率、命中-均衡；调度把它们标价，不消解。</li><li>好机制的共同形状是「常数化」：最坏步时延、抢占事件、迁移时间都有配置上界。</li><li>永不碰的四件：只报吞吐不报分位、按请求数配额、无滞回的抢占、跨租户共享缓存键。</li><li>每层拿上一层吐不出的余量；任何收益要在 goodput 账本上联评后才算数。</li><li>出处：本课程十二课的综合口径；文献锚点为 Kwon et al., SOSP 2023、Yu et al., OSDI 2022、Zhong et al., OSDI 2024。</li></ul>',5))])}const F=s(d,[["render",C]]);export{c as __pageData,F as default};
